class Animal:
    def speak(self):
        return "sound"
class Dog(Animal):
    def speak(self):
        return "woof"
print(Animal().speak(), Dog().speak())

class Person:
    def __init__(self, name):
        self.name = name
class Student(Person):
    def __init__(self, name, score):
        super().__init__(name)
        self.score = score
s = Student("Ada", 90)
print(s.name, s.score, isinstance(s, Person))

class Base:
    def label(self):
        return "base"
class Child(Base):
    def label(self):
        return super().label() + "+child"
print(Child().label())

